package dev.pocket.agent;

import android.app.*;
import android.content.*;
import android.graphics.Typeface;
import android.net.Uri;
import android.os.*;
import android.text.InputType;
import android.view.*;
import android.widget.*;
import org.json.*;

/** Project tools embedded in the bot shell, including a shared /workspace shell. */
final class BotWorkspace {
    private final BotsActivity app;private final Handler main=new Handler(Looper.getMainLooper());
    private LinearLayout body;private String project="",directory=".",screen="",terminalId="";private int generation;private TerminalCanvas terminal;
    BotWorkspace(BotsActivity app){this.app=app;}
    void stop(){generation++;main.removeCallbacksAndMessages(null);terminal=null;}
    private int dp(int n){return app.dp(n);}
    private LinearLayout column(){return app.column();}
    private LinearLayout row(){return app.row();}
    private TextView text(String s,int n){return app.text(s,n);}
    private Button button(LinearLayout p,String s,Runnable click){return app.button(p,s,click,false);}
    private LinearLayout scrolling(){ScrollView scroll=new ScrollView(app);LinearLayout content=column();content.setPadding(dp(4),dp(12),dp(4),dp(16));scroll.addView(content);body.addView(scroll,new LinearLayout.LayoutParams(-1,-1));return content;}
    void show(LinearLayout parent,String tab,String id){stop();body=parent;body.removeAllViews();project=id;screen=tab;if(tab.equals("Terminal"))terminal();else if(tab.equals("Files"))files();else if(tab.equals("Settings"))settings();else if(tab.equals("Servers"))servers();}
    private String scope(){return project.isEmpty()?"root":project;}
    private void terminal(){
        final int epoch=generation;final String key="shell-"+scope();terminalId=app.getSharedPreferences("bot-tools",0).getString(key,"");
        body.addView(app.muted(project.isEmpty()?"Main terminal /workspace - installed tools are shared by every bot":"Bot project terminal",12));
        LinearLayout keys=row();HorizontalScrollView strip=new HorizontalScrollView(app);strip.addView(keys);body.addView(strip);
        String[] names={"Esc","Tab","Ctrl-C","Ctrl-D","Up","Down"};String[] values={"\u001b","\t","\u0003","\u0004","\u001b[A","\u001b[B"};for(int i=0;i<values.length;i++){String value=values[i];button(keys,names[i],()->send(app.json("data",value)));}
        button(keys,"Paste",()->{if(terminal!=null)terminal.paste();});button(keys,"New shell",()->{if(!terminalId.isEmpty())app.request("DELETE","/terminals/"+terminalId,null,v->{});app.getSharedPreferences("bot-tools",0).edit().remove(key).apply();show(body,"Terminal",project);});
        terminal=new TerminalCanvas(app,new TerminalCanvas.Input(){public void send(String s){BotWorkspace.this.send(app.json("data",s));}public void resize(int cols,int rows){BotWorkspace.this.send(app.json("data","","cols",cols,"rows",rows));}});body.addView(terminal,new LinearLayout.LayoutParams(-1,0,1));
        if(terminalId.isEmpty())app.request("POST","/terminals",app.json("projectId",project,"root",project.isEmpty()),v->{String id=((JSONObject)v).optString("id");app.getSharedPreferences("bot-tools",0).edit().putString(key,id).apply();if(epoch!=generation)return;terminalId=id;send(app.json("data","","cols",terminal.columns(),"rows",terminal.rows()));pollTerminal(epoch);});else pollTerminal(epoch);
    }
    private void send(JSONObject data){if(!terminalId.isEmpty())app.terminalInput(terminalId,data);}
    private void pollTerminal(int epoch){if(epoch!=generation||terminal==null)return;app.requestQuiet("GET","/terminals/"+terminalId,null,v->{if(epoch!=generation||terminal==null)return;JSONObject output=(JSONObject)v;terminal.append(output.optString("output"),output.optLong("offset"));if(output.optBoolean("exited"))body.addView(app.muted("Shell exited. Tap New shell to restart.",12));else main.postDelayed(()->pollTerminal(epoch),400);},()->{if(epoch==generation){app.getSharedPreferences("bot-tools",0).edit().remove("shell-"+scope()).apply();terminalId="";show(body,"Terminal",project);}});}
    private void files(){
        final int epoch=generation;LinearLayout content=scrolling();LinearLayout bar=row();content.addView(bar);TextView path=text(directory.equals(".")?"Project files":directory,16);path.setTypeface(Typeface.MONOSPACE);bar.addView(path,new LinearLayout.LayoutParams(0,-2,1));button(bar,"Up",()->{int slash=directory.lastIndexOf('/');directory=slash<0?".":directory.substring(0,slash);show(body,"Files",project);});button(bar,"+ File",()->{EditText name=new EditText(app);AgentStyle.input(name);name.setHint("src/example.js");new AlertDialog.Builder(app).setTitle("New file").setView(name).setPositiveButton("Create",(d,w)->editFile((directory.equals(".")?"":directory+"/")+name.getText(),"")).setNegativeButton("Cancel",null).show();});
        content.addView(app.muted("Tap a file to edit. Folders open here.",12));
        app.request("GET","/files?projectId="+AgentApi.encode(project)+"&path="+AgentApi.encode(directory),null,v->{if(epoch!=generation)return;JSONArray entries=(JSONArray)v;if(entries.length()==0)content.addView(app.muted("This folder is empty.",14));for(int i=0;i<entries.length();i++){JSONObject entry=entries.optJSONObject(i);String pathName=(directory.equals(".")?"":directory+"/")+entry.optString("name");LinearLayout item=row();item.setPadding(dp(10),dp(12),dp(10),dp(12));TextView icon=text(entry.optBoolean("directory")?"DIR":"FILE",10);icon.setTextColor(AgentStyle.MUTED);item.addView(icon,new LinearLayout.LayoutParams(dp(48),-2));TextView name=text(entry.optString("name"),14);name.setTypeface(Typeface.MONOSPACE);item.addView(name,new LinearLayout.LayoutParams(0,-2,1));item.addView(app.muted(entry.optBoolean("directory")?">":entry.optLong("size")+" B",11));content.addView(item);View line=new View(app);line.setBackgroundColor(AgentStyle.BORDER);content.addView(line,new LinearLayout.LayoutParams(-1,dp(1)));item.setOnClickListener(w->{if(entry.optBoolean("directory")){directory=pathName;show(body,"Files",project);}else app.request("GET","/file?projectId="+AgentApi.encode(project)+"&path="+AgentApi.encode(pathName),null,result->editFile(pathName,((JSONObject)result).optString("content")));});}});
    }
    private void editFile(String path,String source){EditText editor=new EditText(app);AgentStyle.input(editor);editor.setTypeface(Typeface.MONOSPACE);editor.setTextSize(13);editor.setGravity(Gravity.TOP);editor.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE|InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);editor.setText(source);editor.setMinLines(16);ScrollView scroll=new ScrollView(app);scroll.addView(editor);AlertDialog dialog=new AlertDialog.Builder(app).setTitle(path).setView(scroll).setPositiveButton("Save",null).setNegativeButton("Close",null).create();String id=project;dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->app.request("PUT","/file",app.json("projectId",id,"path",path,"content",editor.getText().toString()),r->{dialog.dismiss();if(screen.equals("Files"))show(body,"Files",project);})));dialog.show();}
    private void settings(){
        LinearLayout content=scrolling();JSONObject saved=app.currentState().optJSONObject("settings");if(saved==null)return;content.addView(text("Bring Your Own Key",22));content.addView(app.muted("One model connection for all your bots.",12));
        Spinner protocol=new Spinner(app);protocol.setAdapter(new ArrayAdapter<>(app,android.R.layout.simple_spinner_dropdown_item,new String[]{"OpenAI Responses","OpenAI Compatible","Anthropic Compatible"}));String api=saved.optString("api");protocol.setSelection(api.equals("anthropic-messages")?2:api.equals("openai-completions")?1:0);content.addView(protocol);
        EditText base=app.field(content,"Base URL",saved.optString("baseUrl"),false),key=app.field(content,saved.optBoolean("hasKey")?"API key - saved; blank keeps it":"API key","",true),model=app.field(content,"Model name",saved.optString("model"),false);base.setTypeface(Typeface.MONOSPACE);model.setTypeface(Typeface.MONOSPACE);
        CheckBox reveal=new CheckBox(app);reveal.setText("Show API key");reveal.setTextColor(AgentStyle.MUTED);content.addView(reveal);reveal.setOnCheckedChangeListener((v,on)->key.setTransformationMethod(on?null:android.text.method.PasswordTransformationMethod.getInstance()));
        LinearLayout advanced=column();button(content,"Advanced model options",()->advanced.setVisibility(advanced.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE));content.addView(advanced);advanced.setVisibility(View.GONE);EditText context=app.field(advanced,"Context tokens",saved.optString("contextWindow"),false),max=app.field(advanced,"Maximum output tokens",saved.optString("maxTokens"),false);
        java.util.function.Supplier<JSONObject> connection=()->app.json("provider",protocol.getSelectedItemPosition()==2?"anthropic":"openai","api",protocol.getSelectedItemPosition()==2?"anthropic-messages":protocol.getSelectedItemPosition()==1?"openai-completions":"openai-responses","baseUrl",base.getText().toString().trim(),"model",model.getText().toString().trim(),"apiKey",key.getText().toString(),"contextWindow",Integer.parseInt(context.getText().toString()),"maxTokens",Integer.parseInt(max.getText().toString()));
        LinearLayout actions=row();content.addView(actions);app.button(actions,"Save settings",()->{try{app.request("PUT","/settings",connection.get(),v->{app.currentState().put("settings",v);key.setText("");Toast.makeText(app,"Model connection saved",Toast.LENGTH_SHORT).show();});}catch(Exception e){app.error(e);}},true);button(actions,"Test API",()->{try{app.request("POST","/settings/test",connection.get(),v->Toast.makeText(app,"Connected",Toast.LENGTH_SHORT).show());}catch(Exception e){app.error(e);}});
        button(content,"Setup & permissions",app::showSetup);content.addView(app.muted("All tools and project files run on your phone. Model requests go to this provider.",12));
        content.addView(text("Git identity",18));EditText name=app.field(content,"Name","",false),email=app.field(content,"Email","",false);app.request("GET","/git/identity",null,v->{name.setText(((JSONObject)v).optString("name"));email.setText(((JSONObject)v).optString("email"));});button(content,"Save Git identity",()->app.request("PUT","/git/identity",app.json("name",name.getText().toString(),"email",email.getText().toString()),v->Toast.makeText(app,"Git identity saved",Toast.LENGTH_SHORT).show()));
    }
    private void servers(){
        LinearLayout content=scrolling();content.addView(text("Servers & sharing",22));content.addView(app.muted("Local previews open on this device. A Dev Tunnel provides a public link for another phone.",12));EditText port=app.field(content,"Port","3000",false),command=app.field(content,"Server command","npm run dev -- --host 0.0.0.0 --port 3000",false);button(content,"Start server",()->{try{app.request("POST","/servers",app.json("projectId",project,"cwd",".","port",Integer.parseInt(port.getText().toString()),"command",command.getText().toString()),v->show(body,"Servers",project));}catch(Exception e){app.error(e);}});
        button(content,"Sign in to Dev Tunnels",()->app.request("POST","/tunnels/login",app.json(),v->show(body,"Servers",project)));CheckBox publicAccess=new CheckBox(app);publicAccess.setText("Allow anyone with the link");publicAccess.setTextColor(AgentStyle.TEXT);content.addView(publicAccess);button(content,"Create public link",()->{try{app.request("POST","/tunnels",app.json("port",Integer.parseInt(port.getText().toString()),"anonymous",publicAccess.isChecked()),v->show(body,"Servers",project));}catch(Exception e){app.error(e);}});button(content,"Refresh links & logs",()->show(body,"Servers",project));
        app.request("GET","/state",null,v->{if(!screen.equals("Servers"))return;JSONArray list=((JSONObject)v).optJSONArray("jobs");for(int i=list.length()-1;i>=0;i--){JSONObject job=list.optJSONObject(i);content.addView(text(job.optString("label")+" - "+job.optString("status"),15));if(job.optInt("port")>0){String url="http://127.0.0.1:"+job.optInt("port");button(content,"Open local preview :"+job.optInt("port"),()->app.openUrl(url));}TextView log=text(job.optString("output"),12);log.setTypeface(Typeface.MONOSPACE);log.setAutoLinkMask(android.text.util.Linkify.WEB_URLS);log.setMovementMethod(android.text.method.LinkMovementMethod.getInstance());log.setTextIsSelectable(true);content.addView(log);if(job.optString("status").equals("running"))button(content,"Stop process",()->app.request("POST","/processes/"+job.optString("id")+"/stop",app.json(),r->show(body,"Servers",project)));}});
    }
}
